def reverse_sublist(head, left, right):
    dummy = {"val": 0, "next": head}
    before = dummy
    for _ in range(left - 1):
        before = before["next"]
    start = before["next"]
    for _ in range(right - left):
        moved = start["next"]
        start["next"] = moved["next"]
        moved["next"] = before["next"]
        before["next"] = moved
    return dummy["next"]
